function read(teamId=currentTeam().id){let state;try {const saved=JSON.parse(localStorage.getItem(teamKey('mw-expert-agents-v1',teamId))||'null');if(saved&&['agents','squads','members','tasks'].every(k=>Array.isArray(saved[k])))state=saved;}catch{}state=state||expertTeamSeed(seed,teamId);for(const a of state.agents){a.harness=a.harness||(/Claude/.test(a.runtime)?'Claude':/Cursor/.test(a.runtime)?'Cursor':/Qoder/.test(a.runtime)?'Qoder':'Codex');}try{const shared=JSON.parse(localStorage.getItem(teamKey('mw-multica-workspace-v4',teamId))||'{}');const issues=shared.issues||[];if(Array.isArray(shared.issues))state.tasks=state.tasks.filter(t=>!t.boardId||issues.some(i=>i.id===t.boardId||i.expertTaskId===t.id));for(const task of state.tasks){const issue=issues.find(i=>i.id===task.boardId||i.expertTaskId===task.id);if(!issue)continue;Object.assign(task,{status:issue.status,title:issue.title,description:issue.description});const a=state.agents.find(a=>a.name===issue.assignee),s=state.squads.find(s=>s.name===issue.assignee);task.kind=a?'agent':s?'squad':'member';task.target=a?.id||s?.id||issue.assignee;}}catch{}return state;}
export function readExpertWorkspace(teamId=currentTeam().id){return read(teamId)}
function action(label,actionName,id='',extra='',className='aw-button'){return `<button type="button" class="${className}" data-action="${actionName}" data-id="${esc(id)}" ${extra}>${label}</button>`;}
function option(value,label=value,selected=false){return `<option value="${esc(value)}" ${selected?'selected':''}>${esc(label)}</option>`;}
function field(label,name,value='',type='text',extra=''){return `<label class="aw-field"><span>${label}</span><input name="${name}" value="${esc(value)}" type="${type}" ${extra}></label>`;}
function textarea(label,name,value='',extra=''){return `<label class="aw-field"><span>${label}</span><textarea name="${name}" ${extra}>${esc(value)}</textarea></label>`;}
function select(label,name,values,value){return `<label class="aw-field"><span>${label}</span><select name="${name}">${values.map(v=>option(v,v,v===value)).join('')}</select></label>`;}
function avatar(entity,squad=false,small=false){return `<span class="aw-avatar ${small?'aw-avatar-small':''} aw-${entity?.color||'blue'}">${entity?.avatar?`<img src="${esc(entity.avatar)}" alt="">`:icon(squad?'users':'bot',small?17:25)}</span>`;}
function badge(agent){return `<span class="aw-status ${agent.archived?'aw-muted':agent.status==='在线'?'aw-online':'aw-offline'}"><i></i>${agent.archived?'已归档':esc(agent.status)}</span>`;}

class AgentWorkspace extends HTMLElement {
 connectedCallback(){
  this.state=read();this.section=document.body.dataset.page==='squads'?'squads':'agents';this.query='';this.scope='全部';this.status='全部状态';this.layout=localStorage.getItem('mw-agent-layout')||'grid';this.detailTab='概览';
  this.onClick=e=>{const el=e.target.closest('[data-action]');if(el&&this.contains(el))this.handle(el.dataset.action,el.dataset.id,el);};
  this.onInput=e=>{
   if(e.target.name==='description'){const count=this.querySelector('[data-description-count]');if(count)count.textContent=e.target.value.length;}
   if(e.target.name==='runtime-search')this.querySelectorAll('.aw-runtime-row').forEach(x=>x.hidden=!x.textContent.toLowerCase().includes(e.target.value.toLowerCase()));
   if(e.target.name==='member-search')this.querySelectorAll('[data-member-name]').forEach(x=>x.hidden=!x.dataset.memberName.includes(e.target.value.toLowerCase()));
   if(e.target.name==='members'){const box=this.querySelector('.aw-selected-members');if(box)box.textContent=[...this.querySelectorAll('input[name=members]:checked')].map(x=>this.member({type:x.value.split(':')[0],id:x.value.split(':')[1]})?.name).join(' · ');}
  if(e.target.name==='search'&&e.type==='input'){this.query=e.target.value;this.renderResults();}if(e.target.name==='status-filter'){this.status=e.target.value;this.renderResults();}};
  this.onSubmit=e=>{if(e.target.matches('form[data-form]')){e.preventDefault();this.submit(e.target);}};
  this.addEventListener('click',this.onClick);this.addEventListener('input',this.onInput);this.addEventListener('change',this.onInput);this.addEventListener('submit',this.onSubmit);
  this.onPop=()=>{this.settingsSection=null;this.closePropertyPicker?.();this.closeObjectMenu?.();this.detailTab='概览';this.render();const view=new URLSearchParams(location.search).get('view');if(this.item&&!this.isSquad&&['general','access','env','custom_args','skills','mcp'].includes(view))this.openSettings(view);};window.addEventListener('popstate',this.onPop);
  this.onStorage=e=>{if(e.key===STORAGE()||e.key===teamKey('mw-multica-workspace-v4')){this.state=read();if(!this.querySelector('dialog[open]'))this.render();}};window.addEventListener('storage',this.onStorage);this.syncWorkspace(this.state);localStorage.setItem(STORAGE(),JSON.stringify(this.state));this.render();const section=new URLSearchParams(location.search).get('view');if(this.item&&!this.isSquad&&['general','access','env','custom_args','skills','mcp'].includes(section))this.openSettings(section);
 }
 disconnectedCallback(){this.closePropertyPicker?.();this.closeObjectMenu?.();this.removeEventListener('click',this.onClick);this.removeEventListener('input',this.onInput);this.removeEventListener('change',this.onInput);this.removeEventListener('submit',this.onSubmit);window.removeEventListener('popstate',this.onPop);window.removeEventListener('storage',this.onStorage);}
 get isSquad(){return this.section==='squads';}
 get item(){const id=new URLSearchParams(location.search).get('id');return this.state[this.section].find(x=>x.id===id&&(!this.isSquad||!x.archived));}
 get activeAgents(){return this.state.agents.filter(a=>!a.archived);}
 agent(id){return this.state.agents.find(a=>a.id===id);}
 member(m){return (m.type==='agent'?this.state.agents:this.state.members).find(x=>x.id===m.id);}
 save(mutator){const next=structuredClone(this.state);mutator(next);try{this.syncWorkspace(next);localStorage.setItem(STORAGE(),JSON.stringify(next));this.state=next;return true;}catch{this.notify('无法保存，请检查浏览器存储空间后重试。');return false;}}
 syncWorkspace(next){
  const key=teamKey('mw-multica-workspace-v4');let stored={};try{stored=JSON.parse(localStorage.getItem(key)||'{}')||{}}catch{}const shared={...getWorkspaceSeed(),...stored};shared.agents=shared.agents||[];shared.squads=shared.squads||[];shared.issues=shared.issues||[];shared.agents=shared.agents.filter(a=>!a.expertId||next.agents.some(x=>x.id===a.expertId&&!x.archived));shared.squads=shared.squads.filter(a=>!a.expertId||next.squads.some(x=>x.id===a.expertId&&!x.archived));
  shared.members=shared.members||[];for(const m of next.members){let person=shared.members.find(v=>v.expertId===m.id||v.name===m.name);if(person)Object.assign(person,{name:m.name,email:m.email,role:m.role,expertId:m.id});else shared.members.push({...m,expertId:m.id});}
  for(const a of next.agents.filter(a=>!a.archived)){const values={name:a.name,description:a.description,runtime:a.runtime,visibility:a.access,instructions:a.instructions,model:a.model,online:a.status==='在线',runs:a.runs,skills:a.skills};const existing=shared.agents.find(x=>x.name===a.name||x.expertId===a.id);if(existing){const old=existing.name;if(old!==a.name)shared.issues.forEach(i=>{if(i.assignee===old)i.assignee=a.name});Object.assign(existing,values,{expertId:a.id});}else shared.agents.push({...values,expertId:a.id});}
  for(const s of next.squads.filter(s=>!s.archived)){const values={expertId:s.id,name:s.name,description:s.description,leader:next.agents.find(a=>a.id===s.leader)?.name,members:s.members.map(m=>this.member(m)?.name).filter(Boolean)};const existing=shared.squads.find(x=>x.name===s.name||x.expertId===s.id);if(existing){const old=existing.name;if(old!==s.name)shared.issues.forEach(i=>{if(i.assignee===old)i.assignee=s.name});Object.assign(existing,values);}else shared.squads.push(values);}
  for(const task of next.tasks){
   let issue=shared.issues.find(i=>i.expertTaskId===task.id||i.id===task.boardId);if(issue&&!issue.expertTaskId)issue.expertTaskId=task.id;const target=next[task.kind==='squad'?'squads':'agents'].find(x=>x.id===task.target);
   if(!issue){issue={id:Math.max(3,...shared.issues.map(i=>i.id))+1,expertTaskId:task.id,title:task.title,description:task.description||'',project:'',status:task.status,priority:'无优先级',assignee:target?.name||'无负责人',subscribed:true,pinned:false,createdAt:new Date().toISOString()};shared.issues.push(issue);}else{const previous=this.state.tasks.find(t=>t.id===task.id);if(previous&&previous.status!==task.status)issue.status=task.status;else task.status=issue.status;const previousTarget=previous?this.state[previous.kind==='squad'?'squads':'agents'].find(x=>x.id===previous.target):null;if(previous&&(previous.target!==task.target||previous.kind!==task.kind||previousTarget?.name!==target?.name))issue.assignee=target?.name||'无负责人';}task.boardId=issue.id;
  }
  localStorage.setItem(key,JSON.stringify(shared));window.dispatchEvent(new Event('mw-workspace-change'));
 }
 notify(message){const dialog=this.querySelector('dialog[open]');if(dialog){let feedback=dialog.querySelector('.aw-dialog-feedback');if(!feedback){feedback=document.createElement('p');feedback.className='aw-dialog-feedback';feedback.setAttribute('role','status');(dialog.querySelector('.aw-settings-content')||dialog.querySelector('.aw-dialog-body')).append(feedback);}feedback.textContent=message;return;}window.dispatchEvent(new CustomEvent('design-toast',{detail:message}));}
 navigate(id=''){this.settingsSection=null;this.closePropertyPicker?.();this.closeObjectMenu?.();const url=new URL(location.href);id?url.searchParams.set('id',id):url.searchParams.delete('id');url.searchParams.delete('view');history.pushState(null,'',url);this.detailTab='概览';this.render();}
 render(){
  const item=this.item;const missing=new URLSearchParams(location.search).has('id')&&!item;
  this.innerHTML=`<div class="aw-page"><header class="design-module-header aw-header"><nav class="aw-top-tabs" aria-label="专家工作区">${[['skills','技能','skill'],['experts','专家','expert'],['tools','工具','tool']].map(([p,t,i])=>`<a href="${p}.html" class="aw-top-tab"><img src="expert-workspace-icons/${i}.svg" alt="">${t}</a>`).join('')}<a href="agents.html" class="aw-top-tab aw-active" aria-current="page">${icon('bot',20)}智能体</a></nav><span class="aw-demo-label">本地演示 · 自动保存</span></header><div class="aw-body"><nav class="aw-section-tabs" aria-label="智能体模块"><a href="agents.html" class="${!this.isSquad?'aw-selected':''}" ${!this.isSquad?'aria-current="page"':''}>${icon('bot')}智能体 <span>${this.activeAgents.length}</span></a><a href="squads.html" class="${this.isSquad?'aw-selected':''}" ${this.isSquad?'aria-current="page"':''}>${icon('users')}小队 <span>${this.state.squads.filter(s=>!s.archived).length}</span></a>${this.isSquad?action(icon('users',16)+'工作区成员','members','','','aw-button aw-member-button'):''}</nav>${missing?`<div class="aw-empty">${icon('search',32)}<h2>未找到${this.isSquad?'小队':'智能体'}</h2>${action('返回列表','back')}</div>`:item?this.detail(item):this.list()}<footer class="aw-footnote">${icon('monitor',14)}此处为演示数据，创建的任务不会调用真实模型。</footer></div></div>`;
 }
 list(){return `<div class="aw-heading"><div><h1>${this.isSquad?'小队':'智能体'}</h1></div>${action(icon('plus')+(this.isSquad?'创建小队':'创建智能体'),'create','','','aw-button aw-primary')}</div><div class="aw-toolbar"><div class="aw-scopes" role="group" aria-label="查看范围">${(this.isSquad?['全部','我创建的']:['全部','我的','已归档']).map(s=>action(s==='全部'?(this.isSquad?'全部小队':'全部智能体'):s,'scope',s,`aria-pressed="${this.scope===s}"`,'aw-scope '+(this.scope===s?'aw-selected':''))).join('')}</div><div class="aw-filters"><label class="aw-search">${icon('search',16)}<input name="search" aria-label="${this.isSquad?'搜索小队':'搜索智能体'}" placeholder="${this.isSquad?'搜索小队名称、描述':'搜索名称、描述或模型'}" value="${esc(this.query)}"></label>${!this.isSquad?`<select name="status-filter" aria-label="状态筛选">${['全部状态','在线','离线'].map(s=>option(s,s,this.status===s)).join('')}</select>`:''}<div class="aw-view-toggle">${action(icon('grid',16),'layout','grid',`aria-label="卡片视图" aria-pressed="${this.layout==='grid'}"`,'aw-icon-button '+(this.layout==='grid'?'aw-selected':''))}${action(icon('list',16),'layout','list',`aria-label="列表视图" aria-pressed="${this.layout==='list'}"`,'aw-icon-button '+(this.layout==='list'?'aw-selected':''))}</div></div></div><div id="aw-results">${this.results()}</div>`;}
 filtered(){const q=this.query.trim().toLowerCase();return this.state[this.section].filter(x=>this.scope==='已归档'?x.archived:!x.archived).filter(x=>!['我的','我创建的'].includes(this.scope)||x.owner==='我').filter(x=>this.isSquad||this.status==='全部状态'||x.status===this.status).filter(x=>(x.name+' '+x.description+' '+(x.model||'')).toLowerCase().includes(q));}
 results(){const found=this.filtered();return `<div class="aw-result-caption">${found.length} 个${this.isSquad?'小队':'智能体'}${!this.isSquad&&this.scope!=='已归档'?`<span><i class="aw-dot"></i>${found.filter(a=>a.status==='在线').length} 个在线</span>`:''}</div>${!found.length?`<div class="aw-empty">${icon(this.isSquad?'users':'bot',36)}<h2>${this.query||this.status!=='全部状态'?'没有找到匹配结果':this.scope==='已归档'?'暂无已归档智能体':'这里还没有'+(this.isSquad?'小队':'智能体')}</h2><p>${this.query?'试试其他关键词，或清除筛选条件。':'创建你的协作者，开始组织工作。'}</p>${this.query||this.status!=='全部状态'?action('清除筛选','reset'):action(this.isSquad?'创建小队':'创建智能体','create','','','aw-button aw-primary')}</div>`:this.layout==='grid'?`<div class="aw-grid">${found.map(x=>this.isSquad?this.squadCard(x):this.agentCard(x)).join('')}</div>`:this.table(found)}`;}
 renderResults(){const results=this.querySelector('#aw-results');if(results)results.innerHTML=this.results();}
 agentCard(a){const squads=this.state.squads.filter(s=>!s.archived&&s.members.some(m=>m.type==='agent'&&m.id===a.id));return `<button type="button" class="aw-card" data-action="open" data-id="${a.id}"><div class="aw-card-top">${avatar(a)}<h2>${esc(a.name)}</h2>${badge(a)}</div><p class="aw-card-description">${esc(a.description||'尚未添加描述')}</p><div class="aw-card-tags">${a.skills.slice(0,3).map(s=>`<span>${esc(s)}</span>`).join('')||'<span>暂未添加技能</span>'}</div><div class="aw-card-meta"><span>${icon('monitor',14)}${esc(a.runtime)}</span><span>${icon('spark',14)}${esc(a.model)}</span></div><div class="aw-card-footer"><span>${a.owner==='我'?'我创建的':esc(a.owner)+' 创建'}<i>·</i>${squads.length} 个小队</span><span>查看详情 ${icon('arrow',13)}</span></div></button>`;}
 squadCard(s){const leader=this.agent(s.leader);return `<button type="button" class="aw-card aw-squad-card" data-action="open" data-id="${s.id}"><div class="aw-card-top">${avatar(s,true)}<h2>${esc(s.name)}</h2><span class="aw-count-badge">${s.members.length} 位</span></div><p class="aw-card-description">${esc(s.description||'尚未添加描述')}</p><div class="aw-leader">${icon('crown',16)}<span>队长</span>${avatar(leader,false,true)}<strong>${esc(leader?.name||'未指定')}</strong></div><div class="aw-member-preview">${s.members.slice(0,5).map(m=>`<span title="${esc(this.member(m)?.name)}" class="aw-member-initial ${m.type==='human'?'aw-human':''}">${m.type==='human'?esc(this.member(m)?.name?.slice(0,1)||'?'):icon('bot',15)}</span>`).join('')}<span>${s.members.filter(m=>m.type==='agent').length} 个智能体 · ${s.members.filter(m=>m.type==='human').length} 位成员</span></div><div class="aw-card-footer"><span>${s.owner==='我'?'我创建的':esc(s.owner)+' 创建'}</span><span>查看小队 ${icon('arrow',13)}</span></div></button>`;}
 table(items){return `<div class="aw-table-wrap"><table class="aw-table"><thead><tr><th>${this.isSquad?'小队':'智能体'}</th><th>${this.isSquad?'队长':'状态'}</th><th>${this.isSquad?'成员':'运行时'}</th><th>${this.isSquad?'创建者':'模型'}</th><th></th></tr></thead><tbody>${items.map(x=>`<tr><td><button class="aw-name-button" data-action="open" data-id="${x.id}">${avatar(x,this.isSquad,true)}<span><strong>${esc(x.name)}</strong><small>${esc(x.description)}</small></span></button></td><td>${this.isSquad?esc(this.agent(x.leader)?.name):badge(x)}</td><td>${this.isSquad?x.members.length+' 位成员':esc(x.runtime)}</td><td>${esc(this.isSquad?x.owner:x.model)}</td><td>${action(icon('arrow',16),'open',x.id,'aria-label="查看'+esc(x.name)+'"','aw-icon-button')}</td></tr>`).join('')}</tbody></table></div>`;}
 detail(item){return `<div class="aw-object-toolbar"><div class="aw-breadcrumb">${action(icon('back',16)+(this.isSquad?'小队':'智能体'),'back','','','aw-button aw-plain')}<span>/</span><strong>${esc(item.name)}</strong></div><div class="aw-detail-actions">${!item.archived?action(icon('chat',17)+'对话','chat',item.id,'aria-label="对话"','aw-button'):''}${action(icon('settings',17),'edit',item.id,'aria-label="设置"','aw-icon-button')}${item.archived?action('恢复智能体','restore',item.id,'','aw-button aw-primary'):action(icon('plus',16)+'分配工作','task',item.id,'','aw-button aw-primary')}${action('···','object-menu',item.id,'aria-label="更多操作" aria-haspopup="menu"','aw-icon-button')}${action(icon('panel',17),'toggle-inspector','',`aria-label="${this.inspectorHidden?'显示属性':'收起属性'}" aria-pressed="${!this.inspectorHidden}"`,'aw-icon-button')}</div></div><div class="aw-object-layout ${this.inspectorHidden?'aw-inspector-hidden':''}"><main class="aw-object-main"><div class="aw-detail-heading"><button class="aw-identity-avatar" data-action="quick-avatar" aria-label="更换头像">${avatar(item,this.isSquad)}</button><div><h1><button data-action="quick-name" aria-label="编辑名称">${esc(item.name)}</button></h1><button class="aw-description-edit" data-action="quick-description">${esc(item.description||'添加描述…')}</button></div></div>${this.isSquad?this.squadDetail(item):this.agentDetail(item)}</main>${this.inspectorHidden?'':this.inspector(item)}</div>`;}
 inspector(a){const squad=this.isSquad,pick=(label,key,value)=>action(`<span>${esc(value)}</span>${icon('arrow',12)}`,'property-picker',key,`aria-label="${label}" aria-haspopup="listbox"`,'aw-property-button');return `<aside class="aw-object-inspector"><h2>属性</h2><dl class="aw-properties">${squad?`<dt>队长</dt><dd>${pick('更换队长','leader',this.agent(a.leader)?.name||'选择队长')}</dd><dt>成员</dt><dd><div class="aw-member-preview">${a.members.slice(0,4).map(m=>`<span class="aw-member-initial">${esc(this.member(m)?.name?.[0]||'?')}</span>`).join('')}</div>${a.members.length} 位成员</dd>`:`<dt>状态</dt><dd>${badge(a)}<small>· 空闲</small></dd><dt>所有者</dt><dd><span class="aw-member-initial aw-human">${esc(a.owner?.[0])}</span>${esc(a.owner)}</dd><dt>运行时</dt><dd>${pick('更改运行时','runtime',a.runtime)}</dd><dt>Harness</dt><dd>${esc(a.harness||(/Claude/.test(a.runtime)?'Claude':'Codex'))}</dd><dt>模型</dt><dd>${pick('更改模型','model',a.model)}</dd>`}<dt>${squad?'可见范围':'访问权限'}</dt><dd>${action(esc(a.access||'整个工作区'),squad?'property-picker':'edit-access',squad?'access':a.id,'aria-label="编辑访问权限"','aw-property-button')}</dd>${!squad?`<dt>运行（7 天）</dt><dd>${a.runs||0} 次</dd>`:''}<dt>创建者</dt><dd>${esc(a.owner)}</dd><dt>创建时间</dt><dd>${esc(a.createdAt||'2026-11-09')}</dd>${squad?`<dt>更新时间</dt><dd>${esc(a.updatedAt||a.createdAt||'2026-11-09')}</dd>`:''}</dl>${!squad?action('全部设置 '+icon('arrow',14),'edit',a.id,'','aw-button aw-settings-link'):''}</aside>`;}

 agentDetail(a){const current=this.state.tasks.filter(t=>t.kind==='agent'&&t.target===a.id&&t.status==='进行中');return `<section class="aw-object-section"><div class="aw-panel-heading"><h2>当前 <span>${current.length}</span></h2></div>${current.length?current.map(t=>action(`<span>${icon('clock',16)}${esc(t.title)}</span><small>${esc(t.status)} ${icon('arrow',13)}</small>`,'task-detail',t.id,'','aw-task-row')).join(''):'<div class="aw-section-empty">没有正在进行的工作</div>'}</section>${this.tasks('agent',a.id)}<section class="aw-object-section"><div class="aw-panel-heading"><h2>指令</h2>${action(icon('edit',15)+'编辑','edit-instructions',a.id)}</div><div class="aw-read-instructions">${esc(a.instructions||'还没有指令。为智能体描述职责、工作方式和交付标准。')}</div></section><section class="aw-object-section"><div class="aw-panel-heading"><h2>Skills <span>${a.skills.length}</span></h2>${action(icon('plus',15)+'管理技能','edit-skills',a.id)}</div><div class="aw-detail-skills">${a.skills.map(v=>`<div>${icon('book',18)}<strong>${esc(v)}</strong>${action(icon('close',14),'remove-skill',v,'aria-label="移除技能 '+esc(v)+'"','aw-icon-button')}</div>`).join('')||'<p class="aw-muted">尚未添加技能</p>'}</div></section><section class="aw-object-section"><div class="aw-panel-heading"><h2>参与的小队</h2></div><div class="aw-related">${this.state.squads.filter(x=>!x.archived&&x.members.some(m=>m.type==='agent'&&m.id===a.id)).map(x=>`<a href="squads.html?id=${x.id}">${avatar(x,true,true)}${esc(x.name)}<small>${x.leader===a.id?'队长':'成员'}</small>${icon('arrow',14)}</a>`).join('')||'<p class="aw-muted">尚未加入小队</p>'}</div></section>`;}
 squadDetail(s){return `<section class="aw-object-section"><div class="aw-panel-heading"><h2>成员 <span>${s.members.length}</span></h2>${action(icon('plus',16)+'添加成员','add-member',s.id)}</div><div class="aw-member-list">${s.members.map(m=>{const entity=this.member(m),lead=m.type==='agent'&&m.id===s.leader;return `<div class="aw-member-row"><a class="aw-member-avatar" ${m.type==='agent'?`href="agents.html?id=${m.id}"`:'data-action="members"'} aria-label="查看${esc(entity?.name)}">${m.type==='agent'?avatar(entity,false,true):`<span class="aw-member-initial aw-human">${esc(entity?.name?.slice(0,1))}</span>`}</a><div class="aw-member-info"><span>${m.type==='agent'?`<a href="agents.html?id=${m.id}">${esc(entity?.name)}</a>`:esc(entity?.name)}${lead?`<small class="aw-captain-badge">${icon('crown',11)}队长</small>`:''}<small>${m.type==='agent'?'智能体':'成员'}</small></span>${action(m.role?'· '+esc(m.role):'添加角色…','role',m.type+':'+m.id,'','aw-role-button')}</div><span class="aw-member-status">${m.type==='agent'?badge(entity):''}</span>${action('···','member-menu',m.type+':'+m.id,`aria-label="${esc(entity?.name)} 的操作" aria-haspopup="menu"`,'aw-icon-button')}</div>`}).join('')}</div></section><section class="aw-object-section"><div class="aw-panel-heading"><h2>指引</h2>${action(icon('edit',15)+'编辑','edit-instructions',s.id)}</div><div class="aw-read-instructions">${esc(s.instructions||'队长每次处理分配给此小队的任务时，都会读取这些指引。')}</div></section>${this.tasks('squad',s.id)}`;}
 tasks(kind,id){const tasks=this.state.tasks.filter(t=>t.kind===kind&&t.target===id);let linked=[];try{const shared=JSON.parse(localStorage.getItem(teamKey('mw-multica-workspace-v4'))||'{}');linked=(shared.issues||[]).filter(i=>i.assignee===this.item?.name&&!tasks.some(t=>t.boardId===i.id));}catch{}return `<section class="aw-object-section"><div class="aw-panel-heading"><h2>最近工作 <span>${tasks.length+linked.length}</span></h2><div>${action('查看全部','all-tasks',id)}${!this.item?.archived?action(icon('plus',15)+'分配任务','task',id):''}</div></div>${tasks.length+linked.length?`<div class="aw-task-list">${linked.map(t=>`<a href="work.html?issue=${t.id}" class="aw-task-row"><span>${icon('check',16)}${esc(t.title)}</span><small>${esc(t.status)} ${icon('arrow',13)}</small></a>`).join('')}${tasks.map(t=>action(`<span>${icon('check',16)}${esc(t.title)}</span><small>${esc(t.status)} ${icon('arrow',13)}</small>`,'task-detail',t.id,'','aw-task-row')).join('')}</div>`:'<div class="aw-small-empty">暂无任务，分配一个目标，开始协作。</div>'}</section>`;}
 modal(title,body,form='',submit='保存'){
  this.querySelector('dialog')?.close();this.querySelector('dialog')?.remove();const dialog=document.createElement('dialog');dialog.className='aw-dialog';dialog.setAttribute('aria-labelledby','aw-dialog-title');dialog.innerHTML=`<form ${form?`data-form="${form}"`:'method="dialog"'}><header><h2 id="aw-dialog-title">${title}</h2>${action(icon('close',20),'close','','aria-label="关闭弹窗"','aw-icon-button')}</header><div class="aw-dialog-body">${body}</div><footer>${action(form?'取消':'关闭','close')}${form?`<button class="aw-button aw-primary" type="submit">${submit}</button>`:''}</footer></form>`;this.append(dialog);this.returnFocus=document.activeElement;dialog.addEventListener('close',()=>{dialog.remove();if(this.returnFocus?.isConnected)this.returnFocus.focus();});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom){if(dialog.classList.contains('aw-advanced-settings'))this.requestSettings(null);else dialog.close();}}});dialog.showModal();
 }
 close(){this.querySelector('dialog')?.close();}
 captureWizard(){const form=this.querySelector('form[data-form=wizard]');if(!form||this.wizard.step!==2)return;const d=new FormData(form);for(const key of ['name','description','instructions','model','speed','access','starters','color'])this.wizard[key]=String(d.get(key)||'');this.wizard.skills=d.getAll('skills');this.wizard.allowed=d.getAll('allowed');}
 renderWizard(){
  const w=this.wizard;const steps=`<ol class="aw-wizard-steps" aria-label="创建智能体步骤">${['选择运行时','配置','完成'].map((v,i)=>`<li class="${w.step===i+1?'active':w.step>i+1?'done':''}"><span>${w.step>i+1?'✓':i+1}</span>${v}</li>`).join('')}</ol>`;
  let body='';
  if(w.step===1)body=`<div class="aw-wizard-title"><h2>这个智能体在哪里运行？</h2><label class="aw-search">${icon('search',16)}<input name="runtime-search" placeholder="搜索 harness 或机器" aria-label="搜索 harness 或机器"></label></div><div class="aw-runtime-group"><h3>机器 <span>1</span></h3><div class="aw-machine-heading">${icon('monitor',20)}<strong>xymtopdeMacBook-Air.local</strong><small>你 · 3 个 harness</small><span class="aw-status aw-online"><i></i>在线</span></div><div class="aw-runtime-rows">${[['Claude','2.1.196',runtimes[2]],['Codex','0.150.1',runtimes[1]],['Cursor','2026.08.04-aaa8809','本机 · Cursor']].map(([h,v,r])=>action(`<span class="aw-harness-mark"><img src="assets/runtime-providers/${h.toLowerCase()}.svg" alt=""></span><strong>${h}</strong><small>${v}</small><span class="aw-runtime-radio"></span>`,'wizard-runtime',r,`role="radio" aria-checked="${w.runtime===r}" data-harness="${h}"`,'aw-runtime-row')).join('')}</div><div class="aw-runtime-help"><span>另有 1 台机器仅所有者可用，不在这里显示</span>${action('连接机器','connect-runtime','machine')}</div></div><div class="aw-runtime-group"><h3>云服务 <span>1</span></h3><div class="aw-cloud-runtime"><span class="aw-harness-mark"><img src="assets/runtime-providers/qoder.svg" alt=""></span><span><strong>Qoder Cloud Agents</strong><small>由 Qoder 提供</small></span>${action('连接','connect-runtime','cloud')}</div>${[['Cursor Cloud Agents','Cursor'],['Claude Managed Agents','Anthropic']].map(([n,p])=>`<div class="aw-cloud-runtime aw-unavailable"><span class="aw-harness-mark"><img src="assets/runtime-providers/${n.startsWith("Cursor")?"cursor":"claude"}.svg" alt=""></span><span><strong>${n}</strong><small>由 ${p} 提供</small></span><small>即将推出</small></div>`).join('')}</div>`;
  if(w.step===2)body=`<h2 class="aw-config-title">配置智能体</h2><section class="aw-config-section"><h3>身份</h3><div class="aw-identity-picker"><input name="color" type="hidden" value="${esc(w.color)}">${['blue','violet','cyan','green','amber'].map(c=>action(`<span class="aw-avatar aw-${c}">${icon('bot',22)}</span>`,'color',c,`aria-label="选择${c}头像" aria-pressed="${w.color===c}"`,'aw-color-option')).join('')}</div>${field('名称 <b>*</b>','name',w.name,'text','required maxlength="50" placeholder="给智能体起一个名字" autofocus')}${textarea('描述','description',w.description,'rows="3" maxlength="255" placeholder="描述它的职责与擅长的工作"')}<div class="aw-description-count"><span data-description-count>${w.description.length}</span> / 255</div>${textarea('对话开场建议（可选）','starters',w.starters||'','rows="2" placeholder="每行一条开场建议"')}</section><section class="aw-config-section"><h3>行为与能力</h3>${textarea('指令','instructions',w.instructions,'rows="6" placeholder="告诉智能体如何工作、需要遵守哪些约定…"')}<label class="aw-field"><span>Skills</span></label><div class="aw-checks">${skills.map(v=>`<label><input type="checkbox" name="skills" value="${v}" ${w.skills.includes(v)?'checked':''}>${v}</label>`).join('')}</div></section><section class="aw-config-section"><h3>执行配置</h3><p class="aw-field-help">未指定的选项沿用运行时默认值。</p><div class="aw-selected-runtime">${icon('monitor',18)}<span><strong>${esc(w.harness)}</strong><small>${esc(w.machine||(w.runtime==='云端工作区'?'云端工作区':'xymtopdeMacBook-Air.local'))}</small></span>${action('更换','wizard-back')}</div><input type="hidden" name="runtime" value="${esc(w.runtime)}"><input type="hidden" name="harness" value="${esc(w.harness)}"><div class="aw-form-grid">${select('模型','model',models,w.model)}${select('速度','speed',['运行时默认','快速','标准'],w.speed||'运行时默认')}</div>${select('访问权限','access',['仅自己','整个工作区','指定成员'],w.access)}<div class="aw-access-members"><span>选择可运行此智能体的成员</span>${this.state.members.map(m=>`<label><input type="checkbox" name="allowed" value="${m.id}" ${w.allowed?.includes(m.id)?'checked':''}>${esc(m.name)}</label>`).join('')}</div></section>`;
  if(w.step===3)body=`<div class="aw-wizard-success"><span>${icon('check',30)}</span><h2>智能体已准备就绪</h2><p>${esc(w.name)} 已创建，可以开始对话或分配工作。</p><div class="aw-success-agent">${avatar(this.agent(w.createdId))}<strong>${esc(w.name)}</strong><small>${esc(w.harness)} · ${esc(w.model)}</small></div></div>`;
  this.modal('创建智能体',body,w.step<3?'wizard':'',w.step===1?'下一步':'创建智能体');
  const dialog=this.querySelector('dialog');dialog.classList.add('aw-wizard');const surface=this.closest('.design-panel');if(surface){const place=()=>{const r=surface.getBoundingClientRect();Object.assign(dialog.style,{left:r.left+'px',top:r.top+'px',right:'auto',bottom:'auto',width:r.width+'px',height:r.height+'px',maxWidth:'none',margin:'0'});};place();window.addEventListener('resize',place);dialog.addEventListener('close',()=>window.removeEventListener('resize',place),{once:true});}dialog.querySelector('header h2').insertAdjacentHTML('afterend',steps);
  const footer=dialog.querySelector('footer');footer.insertAdjacentHTML('afterbegin',`<span class="aw-step-caption">第 ${w.step} 步，共 3 步</span>`);
  if(w.step===1)footer.querySelector('[type=submit]').disabled=!w.runtime;
  if(w.step===2)footer.querySelector('[data-action=close]').insertAdjacentHTML('beforebegin',action('上一步','wizard-back'));
  if(w.step===3)footer.innerHTML=`<span class="aw-step-caption">第 3 步，共 3 步</span>${action('查看智能体','wizard-done','','','aw-button aw-primary')}`;
 }
 connectRuntime(kind){this.connectionKind=kind;this.modal(kind==='cloud'?'连接云服务':'连接机器',`<p class="aw-field-help">填写连接信息以继续配置智能体。此设计稿只保留本地配置，不发起真实连接。</p>${field(kind==='cloud'?'API Key':'机器名称','connection','',kind==='cloud'?'password':'text','required placeholder="输入连接信息" autocomplete="off"')}<p class="aw-field-help">真实运行需要连接运行时服务。</p>`,'connect-runtime','保存并继续');this.querySelector('dialog footer [data-action=close]').outerHTML=action('返回选择运行时','connection-back');}
 chatModal(){const a=this.item;this.modal('与 '+esc(a.name)+' 对话',`<div class="aw-agent-chat">${(a.messages||[]).map(m=>`<div><small>我 · ${esc(m.time)}</small><p>${esc(m.text)}</p><span>本地演示 · 未连接模型</span></div>`).join('')||'<p class="aw-small-empty">发送消息，开始与智能体交流。</p>'}</div>`+textarea('消息','message','','rows="3" required autofocus placeholder="希望一起完成什么？"'),'agent-chat','发送');}
 entityForm(existing=null,duplicate=false){
  if(this.isSquad&&!this.activeAgents.length){this.notify('请先创建一个智能体作为队长。');return;}
  const a=existing||{};this.duplicateSource=duplicate?structuredClone(a):null;this.editId=duplicate?'':a.id||'';
  const name=duplicate?a.name+' 副本':a.name||'';
  const common=`<div class="aw-identity-picker"><input name="color" type="hidden" value="${esc(a.color||'blue')}">${['blue','violet','cyan','green','amber'].map(c=>action(`<span class="aw-avatar aw-${c}">${icon(this.isSquad?'users':'bot',20)}</span>`,'color',c,`aria-label="选择${c}头像" aria-pressed="${(a.color||'blue')===c}"`,'aw-color-option')).join('')}</div>`+field((this.isSquad?'小队':'智能体')+'名称 <b>*</b>','name',name,'text','required maxlength="50" placeholder="为协作者取一个名字" autofocus')+textarea('描述','description',a.description||'','rows="3" maxlength="255" placeholder="描述职责与工作目标"')+`<div class="aw-description-count"><span data-description-count>${(a.description||'').length}</span> / 255</div>`;
  this.modal(this.editId?'编辑'+(this.isSquad?'小队':'智能体'):duplicate?'复制智能体':'创建'+(this.isSquad?'小队':'智能体'),common+(this.isSquad?`<label class="aw-field"><span>队长智能体 <b>*</b></span><select name="leader" required>${option('','选择队长')}${this.activeAgents.map(x=>option(x.id,x.name,x.id===a.leader)).join('')}</select></label><label class="aw-field"><span>成员 <small>（可选）</small></span></label><label class="aw-search aw-member-search">${icon('search',15)}<input name="member-search" placeholder="搜索智能体或成员"></label><div class="aw-selected-members"></div><div class="aw-member-options aw-create-members">${[...this.activeAgents.map(x=>({...x,type:'agent'})),...this.state.members.map(x=>({...x,type:'human'}))].map(x=>`<label data-member-name="${esc(x.name.toLowerCase())}"><input type="checkbox" name="members" value="${x.type}:${x.id}" ${a.members?.some(m=>m.id===x.id&&m.type===x.type)?'checked':''}>${x.type==='agent'?avatar(x,false,true):`<span class="aw-member-initial aw-human">${esc(x.name.slice(0,1))}</span>`}<span>${esc(x.name)}</span><small>${x.type==='agent'?'智能体':'成员'}</small></label>`).join('')}</div>${select('访问权限','access',['整个工作区','仅自己'],a.access||'整个工作区')}`:`<div class="aw-form-grid">${select('运行时','runtime',runtimes,a.runtime||runtimes[0])}${select('模型','model',models,a.model||models[0])}</div>${select('访问权限','access',['仅自己','整个工作区','指定成员'],a.access||'仅自己')}<div class="aw-access-members"><span>指定成员（选择“指定成员”时至少选择一位）</span>${this.state.members.filter(m=>m.id!=='me').map(m=>`<label><input type="checkbox" name="allowed" value="${m.id}" ${a.allowed?.includes(m.id)?'checked':''}>${esc(m.name)}</label>`).join('')}</div><details class="aw-form-details"><summary>指令与技能</summary>${textarea('工作指令','instructions',a.instructions||'','rows="4"')}<div class="aw-checks">${skills.map(s=>`<label><input name="skills" type="checkbox" value="${s}" ${a.skills?.includes(s)?'checked':''}>${s}</label>`).join('')}</div></details>`),this.isSquad?'squad':'agent',this.editId?'保存修改':this.isSquad?'创建小队':'创建智能体');
 }
 handle(name,id,el){
  if(name==='wizard-runtime'){this.wizard.runtime=id;this.wizard.harness=el.dataset.harness;this.querySelectorAll('.aw-runtime-row').forEach(x=>x.setAttribute('aria-checked',String(x===el)));this.querySelector('button[type=submit]').disabled=false;return;}
  if(name==='wizard-back'){this.captureWizard();this.wizard.step=1;return this.renderWizard();}
  if(name==='wizard-done'){const id=this.wizard.createdId;this.close();this.wizard=null;return this.navigate(id);}
  if(name==='connect-runtime')return this.connectRuntime(id);
  if(name==='connection-back')return this.renderWizard();
  if(name==='color'){this.querySelector('[name=color]').value=id;this.querySelectorAll('[data-action=color]').forEach(x=>x.setAttribute('aria-pressed',String(x===el)));return;}
  if(name==='leader-name'){const value=this.querySelector('[name=leader]').value;const a=this.activeAgents.find(x=>x.name===value);if(a&&this.save(state=>{const squad=state.squads.find(x=>x.id===id);squad.leader=a.id;if(!squad.members.some(m=>m.type==='agent'&&m.id===a.id))squad.members.push({id:a.id,type:'agent',role:'协调分工与进度'});})){this.render();this.notify('队长已更新');}return;}
  if(name==='edit-instructions')return this.modal(this.isSquad?'编辑小队指引':'编辑指令',textarea('指令','instructions',this.item.instructions,'rows="10" autofocus'),'instructions','保存指令');
  if(name==='edit-skills')return this.modal('管理技能',`<div class="aw-skill-options">${skills.map(v=>`<label><input type="checkbox" name="skills" value="${esc(v)}" ${this.item.skills.includes(v)?'checked':''}>${icon('book',18)}${esc(v)}</label>`).join('')}</div>`,'skills','保存技能');
  if(name==='remove-skill'){if(this.save(state=>{const a=state.agents.find(x=>x.id===this.item.id);a.skills=a.skills.filter(v=>v!==id);})){this.render();this.notify('技能已移除');}return;}
  if(name==='chat'){location.href=this.isSquad?'group-chat.html?squad='+encodeURIComponent(this.item.id):'agents.html?id='+encodeURIComponent(this.item.id)+'&chat=1&new=1';return;}
  if(name==='open')return this.navigate(id);
  if(name==='back')return this.navigate();
  if(name==='scope'){this.scope=id;return this.render();}
  if(name==='layout'){this.layout=id;try{localStorage.setItem('mw-agent-layout',id);}catch{}return this.render();}
  if(name==='reset'){this.query='';this.status='全部状态';return this.render();}
  if(name==='detail-tab'){this.detailTab=id;return this.render();}
  if(name==='create'){this.duplicateSource=null;if(this.isSquad)return this.entityForm();this.editId='';this.wizard={step:1,runtime:'',harness:'',name:'',description:'',instructions:'',skills:[],model:models[0],access:'仅自己',color:'blue'};return this.renderWizard();}
  if(name==='edit'||name==='edit-access')return this.entityForm(this.item);
  if(name==='duplicate'){this.duplicateSource=structuredClone(this.item);this.editId='';this.wizard={...structuredClone(this.item),name:this.item.name+' 副本',step:2};return this.renderWizard();}
  if(name==='close')return this.close();
  if(name==='members')return this.membersModal();
  if(name==='new-human')return this.modal('添加工作区成员',field('姓名 <b>*</b>','name','','text','required maxlength="40" autofocus')+field('邮箱 <b>*</b>','email','','email','required maxlength="120"')+'<p class="aw-field-help">添加演示成员以参与小队协作，不会发送邀请邮件。</p>','human','添加成员');
  if(name==='archive'){
   const item=this.item;
   if(!this.isSquad){const leaders=this.state.squads.filter(s=>!s.archived&&s.leader===id);if(leaders.length)return this.modal('请先更换小队队长',`<p>“${esc(item.name)}”是以下小队的队长。请先在小队详情中指定另一位队长。</p><div class="aw-related">${leaders.map(s=>`<a href="squads.html?id=${s.id}">${esc(s.name)}${icon('arrow',15)}</a>`).join('')}</div>`);}
   return this.modal('归档'+(this.isSquad?'小队':'智能体'),`<p>确定归档“${esc(item.name)}”吗？</p><p class="aw-field-help">${this.isSquad?'小队将从列表中移除，未完成任务转交给原队长。归档后不能恢复。':'归档后不能接收新任务，未完成任务将取消；历史记录保留，可在“已归档”中恢复。'}</p>`,'archive','确认归档');
  }
  if(name==='restore'){if(this.save(s=>{s.agents.find(a=>a.id===id).archived=false;})){this.render();this.notify('智能体已恢复');}return;}
  if(name==='add-member'){
   const s=this.item;const available=[...this.activeAgents.map(a=>({...a,type:'agent'})),...this.state.members.map(m=>({...m,type:'human'}))].filter(x=>!s.members.some(m=>m.id===x.id&&m.type===x.type));
   return this.modal('添加小队成员',available.length?`<div class="aw-member-options">${available.map(x=>`<label><input name="members" type="checkbox" value="${x.type}:${x.id}"><span>${esc(x.name)}</span><small>${x.type==='agent'?'智能体':'工作区成员'}</small></label>`).join('')}</div>`:'<p>所有可用的智能体和成员都已在小队中。</p>',available.length?'add-member':'','添加所选成员');
  }
  if(name==='role'){const [type,memberId]=id.split(':');const m=this.item.members.find(m=>m.id===memberId&&m.type===type);this.memberKey=id;return this.modal('编辑角色分工',textarea('角色说明','role',m.role,'rows="4" maxlength="250" autofocus placeholder="告诉队长，这位成员适合处理什么工作"'),'role');}
  if(name==='remove-member'){this.memberKey=id;const [type,memberId]=id.split(':');const m=this.item.members.find(m=>m.id===memberId&&m.type===type);return this.modal('移除小队成员',`<p>将“${esc(this.member(m)?.name)}”移出当前小队？</p><p class="aw-field-help">该成员仍会保留在工作区中。</p>`,'remove-member','确认移除');}
  if(name==='leader'){const leader=this.querySelector('[name="leader"]').value;if(this.save(s=>{const squad=s.squads.find(x=>x.id===id);squad.leader=leader;if(!squad.members.some(m=>m.type==='agent'&&m.id===leader))squad.members.push({type:'agent',id:leader,role:'协调分工与进度'});})){this.render();this.notify('已更新队长');}return;}
  if(name==='task'){const target=this.item,kind=this.isSquad?'squad':'agent';window.dispatchEvent(new CustomEvent('design-create-board-task',{detail:{initial:{assignee:target.name},onCreated:issue=>{this.save(state=>state.tasks.unshift({id:uid(),boardId:issue.id,title:issue.title,description:issue.description,kind,target:target.id,status:issue.status,created:new Date().toLocaleString('zh-CN')}));this.render();this.notify('任务已创建')}}}));return;}
  if(name==='task-detail'){const task=this.state.tasks.find(t=>t.id===id);if(task.boardId){location.href='work.html?issue='+task.boardId;return;}this.taskId=id;return this.modal('任务详情',`<h3>${esc(task.title)}</h3><p class="aw-task-description">${esc(task.description||'暂无补充说明')}</p>${select('任务状态','status',['待办','进行中','已完成','已取消'],task.status)}<p class="aw-field-help">${esc(task.created)}</p>${task.boardId?`<a class="aw-button" href="work.html?issue=${task.boardId}">在看板中打开 ${icon('arrow',14)}</a>`:''}`,'task-status','保存状态');}
 }
 membersModal(){this.modal('工作区成员',`<div class="aw-panel-heading"><span>${this.state.members.length} 位成员</span>${action(icon('plus',16)+'添加成员','new-human')}</div><div class="aw-workspace-members">${this.state.members.map(m=>`<div><span class="aw-member-initial aw-human">${esc(m.name.slice(0,1))}</span><span><strong>${esc(m.name)}</strong><small>${esc(m.email)}</small></span><small>${esc(m.role)}</small></div>`).join('')}</div>`);}
 submit(form){
  if(form.dataset.form==='wizard'){
   if(this.wizard.step===1){if(!this.wizard.runtime)return;this.wizard.step=2;return this.renderWizard();}
   this.captureWizard();this.wizardCompleting=true;form.dataset.form='agent';this.submit(form);form.dataset.form='wizard';this.wizardCompleting=false;return;
  }
  const data=new FormData(form);const get=n=>String(data.get(n)||'').trim();const kind=form.dataset.form;if(kind==='connect-runtime'){if(!get('connection'))return;this.wizard.runtime=this.connectionKind==='cloud'?'Qoder Cloud Agents':'本机 · Codex';this.wizard.harness=this.connectionKind==='cloud'?'Qoder':'Codex';this.wizard.machine=this.connectionKind==='cloud'?'Qoder Cloud':get('connection');this.wizard.step=2;return this.renderWizard();}const item=this.item;let nextId='';let message='已保存';
  if(['agent','squad'].includes(kind)&&!get('name')){form.elements.name.setCustomValidity('请输入名称');form.elements.name.reportValidity();form.elements.name.oninput=()=>form.elements.name.setCustomValidity('');return;}
  if(kind==='agent-chat'&&!get('message')){this.notify('请输入消息');return;}
  if(kind==='squad'&&this.state.squads.some(a=>a.id!==this.editId&&a.name.toLowerCase()===get('name').toLowerCase())){this.notify('已有同名小队，请使用其他名称');return;}
  if(kind==='task'&&!get('title')){this.notify('请输入任务名称');return;}
  if(kind==='agent'&&this.state.agents.some(a=>a.id!==this.editId&&a.name.toLowerCase()===get('name').toLowerCase())){this.notify('已有同名智能体，请使用其他名称');return;}
  if(kind==='agent'&&get('access')==='指定成员'&&!data.getAll('allowed').length){this.notify('请至少选择一位可以访问的成员');return;}
  if(kind==='add-member'&&!data.getAll('members').length){this.notify('请选择至少一位成员');return;}
  if(kind==='human'&&(!get('name')||this.state.members.some(m=>m.email.toLowerCase()===get('email').toLowerCase()))){this.notify('请填写姓名，并使用尚未添加的邮箱');return;}
  const saved=this.save(state=>{
   if(kind==='agent'){
    const values={color:get('color')||'blue',harness:get('harness')||item?.harness,starters:data.has('starters')?get('starters'):item?.starters||'',speed:data.has('speed')?get('speed'):item?.speed||'运行时默认',updatedAt:new Date().toLocaleDateString('en-CA'),name:get('name'),description:get('description'),runtime:get('runtime'),model:get('model'),status:get('runtime')===runtimes[2]?'离线':'在线',access:get('access'),allowed:data.getAll('allowed'),instructions:get('instructions'),skills:data.getAll('skills')};
    if(this.editId)Object.assign(state.agents.find(a=>a.id===this.editId),values);else{nextId=uid();state.agents.unshift({...this.duplicateSource,...values,messages:[],archived:false,id:nextId,owner:'我',status:values.runtime===runtimes[2]?'离线':'在线',color:get('color')||'blue',harness:get('harness'),speed:get('speed'),starters:get('starters'),createdAt:new Date().toLocaleDateString('en-CA'),runs:0});}message=this.editId?'智能体已更新':'智能体已创建';
   }
   if(kind==='squad'){
    const values={name:get('name'),description:get('description'),leader:get('leader'),access:get('access'),color:get('color')||'blue',updatedAt:new Date().toLocaleDateString('en-CA')};
    if(this.editId){const s=state.squads.find(s=>s.id===this.editId);Object.assign(s,values);if(!s.members.some(m=>m.type==='agent'&&m.id===values.leader))s.members.push({id:values.leader,type:'agent',role:'协调分工与进度'});}else{nextId=uid();state.squads.unshift({...values,id:nextId,owner:'我',createdAt:new Date().toLocaleDateString('en-CA'),instructions:'',members:[{id:values.leader,type:'agent',role:'协调分工与进度'}]});}const target=state.squads.find(x=>x.id===(this.editId||nextId));const selected=data.getAll('members').map(v=>{const [type,id]=v.split(':');return target.members.find(m=>m.type===type&&m.id===id)||{type,id,role:''};});target.members=[{id:values.leader,type:'agent',role:'协调分工与进度'},...selected.filter(m=>!(m.type==='agent'&&m.id===values.leader))];message=this.editId?'小队已更新':'小队已创建';
   }
   if(kind==='instructions')state[this.section].find(x=>x.id===item.id).instructions=get('instructions');
   if(kind==='skills')state.agents.find(x=>x.id===item.id).skills=data.getAll('skills');
   if(kind==='archive'){
    const shared=JSON.parse(localStorage.getItem(teamKey('mw-multica-workspace-v4'))||'{}');(shared.issues||[]).filter(i=>i.assignee===item.name&&!['已完成','已取消'].includes(i.status)).forEach(i=>{if(this.isSquad)i.assignee=this.agent(item.leader)?.name||'无负责人';else i.status='已取消'});localStorage.setItem(teamKey('mw-multica-workspace-v4'),JSON.stringify(shared));
    state[this.section].find(x=>x.id===item.id).archived=true;
    state.tasks.filter(t=>t.kind===(this.isSquad?'squad':'agent')&&t.target===item.id&&!['已完成','已取消'].includes(t.status)).forEach(t=>{if(this.isSquad){t.kind='agent';t.target=item.leader;}else t.status='已取消';});message='已归档';
   }
   if(kind==='add-member'){const s=state.squads.find(s=>s.id===item.id);data.getAll('members').forEach(v=>{const [type,id]=v.split(':');s.members.push({type,id,role:''});});message='已添加小队成员';}
   if(kind==='role'){const [type,id]=this.memberKey.split(':');state.squads.find(s=>s.id===item.id).members.find(m=>m.type===type&&m.id===id).role=get('role');}
   if(kind==='remove-member'){const [type,id]=this.memberKey.split(':');const s=state.squads.find(s=>s.id===item.id);if(!(type==='agent'&&s.leader===id))s.members=s.members.filter(m=>!(m.type===type&&m.id===id));message='成员已移出小队';}
   if(kind==='human'){state.members.push({id:uid(),name:get('name'),email:get('email'),role:'成员'});message='演示成员已添加';}
   if(kind==='task'){state.tasks.unshift({id:uid(),title:get('title'),description:get('description'),kind:this.isSquad?'squad':'agent',target:item.id,status:'待办',created:new Date().toLocaleString('zh-CN')});message='任务已添加到演示记录';}
   if(kind==='agent-chat'){const a=state.agents.find(x=>x.id===item.id);a.messages=[...(a.messages||[]),{text:get('message'),time:new Date().toLocaleTimeString('zh-CN')}];message='消息已保存在本地演示';}
   if(kind==='task-status'){state.tasks.find(t=>t.id===this.taskId).status=get('status');message='任务状态已更新';}
  });
  if(!saved)return;if(this.wizardCompleting&&nextId){this.wizard.createdId=nextId;this.wizard.step=3;this.close();this.render();this.renderWizard();return;}this.close();if(kind==='archive')this.navigate();else if(nextId)this.navigate(nextId);else{if(kind==='task'&&!this.isSquad)this.detailTab='任务与动态';this.render();}if(kind==='human')this.membersModal();if(kind==='agent-chat')this.chatModal();this.notify(message);
 }
}
